// ==UserScript==
// @name         Duck Hunt — звук для SVG
// @namespace    local.duckhunt.audio
// @version      1.2.3
// @description  Оригинальные звуки NES для SVG Duck Hunt: выстрелы, утки, собака, раунды. Без внешних загрузок.
// @match        *://pikuco.ru/*
// @match        *://*.pikuco.ru/*
// @match        file:///*
// @downloadURL  https://raw.githubusercontent.com/antonanatolevic21-del/op-ed-orden/duck-hunt-audio/duck-hunt/duck_hunt_audio.user.js
// @updateURL    https://raw.githubusercontent.com/antonanatolevic21-del/op-ed-orden/duck-hunt-audio/duck-hunt/duck_hunt_audio.user.js
// @run-at       document-end
// @grant        none
// ==/UserScript==

(() => {
  'use strict';
  if (window.DuckHuntAudio) return;
  const PACK = {"bark":"","fall":"","flap":"","flyaway":"","gameover":"","hit":"","laugh":"","perfect":"","pickup":"","round":"","shot":"","start":"","win":"","menu":""};
  // Original NES recordings: https://downloads.khinsider.com/game-soundtracks/album/duck-hunt
  const stats = {events:{}, errors:[], decoded:[]};
  const prefs = {enabled:true, volume:.28};
  try { Object.assign(prefs, JSON.parse(localStorage.getItem('duckhunt-audio-prefs-v1') || '{}')); } catch {}
  prefs.volume = Math.min(1, Math.max(0, Number(prefs.volume) || 0));
  let resumePromise=Promise.resolve();
  let context, master, buffers = new Map(), decoding, db, dbPromise, activeRoot;
  const games = new Map();
  const settingsControls=new Set();
  let menuPreviewPending=false;
  const voices = new Map();
  const voiceVersions = new Map();
  let playbackEpoch=0;
  function stop(name){voiceVersions.set(name,(voiceVersions.get(name)||0)+1);for(const source of voices.get(name)||[]){try{source.stop();}catch{}}voices.delete(name);}
  const stored = new Map();
  const savePrefs = () => {try {localStorage.setItem('duckhunt-audio-prefs-v1',JSON.stringify(prefs));} catch {}};
  const report = error => {stats.errors.push(String(error?.message || error)); if (stats.errors.length>8) stats.errors.shift();};
  function openDB() {
    if (dbPromise) return dbPromise;
    dbPromise = new Promise(resolve => {
      try {
        const request = indexedDB.open('duckhunt-audio-files-v1',1);
        request.onupgradeneeded = () => request.result.createObjectStore('sounds');
        request.onerror = () => resolve(null);
        request.onsuccess = () => {db=request.result;resolve(db);};
        request.onblocked = () => resolve(null);
      } catch {resolve(null);}
    });
    return dbPromise;
  }
  async function loadStored() {
    const database=await openDB();
    if (!database) return;
    await new Promise(resolve=>{
      const tx=database.transaction('sounds','readonly');
      const cursor=tx.objectStore('sounds').openCursor();
      cursor.onsuccess=()=>{const c=cursor.result;if(c){stored.set(c.key,c.value);c.continue();}};
      tx.oncomplete=resolve;tx.onerror=resolve;tx.onabort=resolve;
    });
    if(context) await decodeAll(true);
  }
  function builtinBytes(name) {
    const s=atob(PACK[name]), a=new Uint8Array(s.length);
    for(let i=0;i<s.length;i++)a[i]=s.charCodeAt(i);
    return a.buffer;
  }
  async function decodeAll(force=false) {
    if(decoding && !force) return decoding;
    decoding=Promise.all(Object.keys(PACK).map(async name=>{
      try {
        if(buffers.has(name)&&!force)return;
        const bytes=stored.has(name)?await stored.get(name).arrayBuffer():builtinBytes(name);
        buffers.set(name,await context.decodeAudioData(bytes));
      } catch(error){report(error);}
    })).then(()=>{stats.decoded=[...buffers.keys()];});
    return decoding;
  }
  async function unlock() {
    try {
      if(!context){
        const AudioEngine=window.AudioContext||window.webkitAudioContext;
        if(!AudioEngine)throw Error('В этом браузере нет Web Audio');
        context=new AudioEngine();master=context.createGain();master.gain.value=prefs.volume;master.connect(context.destination);
      }
      // Called synchronously from a trusted click/pointer event before the first await.
      const resuming=context.state==='suspended'?context.resume():Promise.resolve();
      resumePromise=resuming;await resuming;master.gain.setValueAtTime(prefs.enabled?prefs.volume:0,context.currentTime);await decodeAll();refreshUI();return true;
    }catch(error){report(error);refreshUI();return false;}
  }
  function record(name){stats.events[name]=(stats.events[name]||0)+1;}
  async function play(name,delay=0) {
    if(!prefs.enabled)return;
    const epoch=playbackEpoch,version=voiceVersions.get(name)||0;
    record(name);
    try {
      if(!context)return;await resumePromise;if(context.state!=='running')return;
      await decodeAll();
      if(epoch!==playbackEpoch||version!==(voiceVersions.get(name)||0))return;
      const buffer=buffers.get(name);if(!buffer)return;
      const source=context.createBufferSource();source.buffer=buffer;source.connect(master);
      if(!voices.has(name))voices.set(name,new Set());voices.get(name).add(source);
      source.onended=()=>{source.disconnect();voices.get(name)?.delete(source);};
      source.start(context.currentTime+Math.max(0,delay));
      if(name==='fall')source.stop(context.currentTime+delay+.61);
    }catch(error){report(error);}
  }
  const style=(e)=>e.ownerDocument.defaultView.getComputedStyle(e);
  const visible=e=>!!e && style(e).display!=='none' && style(e).visibility==='visible';
  function targetIn(svg){try{return svg.querySelector(':target');}catch{return null;}}
  function hit(game,volley){
    const key=volley.dataset.volley;
    if(game.hits.has(key))return;
    game.hits.add(key);play('fall',.035);play('hit',.68);
  }
  function handleTarget(game) {
    const target=targetIn(game.svg), id=target?.id||(game.svg.ownerDocument.defaultView.location.hash==='#mainmenu'?'mainmenu':'');
    if(!id||id===game.lastTarget)return;
    game.lastTarget=id;
    if(id==='mainmenu'){
      playbackEpoch++;game.introUntil=0;
      game.started=false;game.ended=false;game.hits.clear();game.seen.clear();
      for(const name of Object.keys(PACK))stop(name);activeRoot=null;return;
    }
    if(id==='astart'){
      playbackEpoch++;
      game.introUntil=performance.now()+1000*(parseFloat(game.intro?style(game.intro).animationDuration:'0')||0);
      for(const name of Object.keys(PACK))stop(name);
      game.hits.clear();game.seen.clear();
      activeRoot=game.svg;game.started=true;game.ended=false;play('start');return;
    }
    if(target.classList.contains('q')){
      activeRoot=game.svg;game.started=true;play('shot');
      const volley=target.closest('.v[data-volley]');
      if(volley&&target.classList.contains('caught'))hit(game,volley);
    }
  }
  function pollGame(game) {
    const svg=game.svg;
    if(!svg.isConnected||svg.ownerDocument.hidden)return;
    handleTarget(game);
    if(activeRoot!==svg||!game.started||game.ended)return;
    if(performance.now()<(game.introUntil||0)||(game.introUntil&&visible(game.intro))){
      const notice=game.intro?.querySelector('.introready');
      if(notice&&Number(style(notice).opacity)>.5&&!game.seen.has('bark')){game.seen.add('bark');play('bark');}
      return;
    }
    game.introUntil=0;
    const current=game.volleys.find(e=>visible(e));
    if(current){
      const key=current.dataset.volley;
      if(!game.seen.has('duck:'+key)){game.seen.add('duck:'+key);for(const name of ['start','pickup','laugh','round','perfect'])stop(name);play('flap');}
      const dead=game.hits.has(key);
      if(!dead){
        const marker=current.querySelector('.bird[data-duck]');
        const id=marker?.dataset.duck;
        if(id&&Number(style(svg).getPropertyValue('--d'+id))>.5)hit(game,current);
      }
      const fly=current.querySelector('.flyaway');
      if(visible(fly)&&Number(style(fly).opacity)>.1&&!game.hits.has(key)&&!game.seen.has('away:'+key)){
        game.seen.add('away:'+key);play('flyaway');
      }
      const dog=current.querySelector('.dogshow');
      if(dog&&visible(dog)){
        const Matrix=svg.ownerDocument.defaultView.DOMMatrix;
        const y=new Matrix(style(dog).transform==='none'?undefined:style(dog).transform).m42;
        if(y<65&&!game.seen.has('dog:'+key)){
          game.seen.add('dog:'+key);
          play(game.hits.has(key)?'pickup':'laugh');
        }
      }
    }
    for(const result of game.results){
      if(!visible(result)||game.seen.has(result))continue;
      game.seen.add(result);
      const perfect=result.querySelector('.perfect');
      play(perfect&&Number(style(perfect).opacity)>.5?'perfect':'round');
    }
    for(const over of game.overs){
      if(!visible(over))continue;
      const Matrix=svg.ownerDocument.defaultView.DOMMatrix;
      const x=new Matrix(style(over).transform==='none'?undefined:style(over).transform).m41;
      if(Math.abs(x)<800){game.ended=true;play('gameover');return;}
    }
    if(game.win&&visible(game.win)){game.ended=true;play('win');}
    const notice=game.intro?.querySelector('.introready');
    if(game.intro&&visible(game.intro)&&(!notice||Number(style(notice).opacity)>.5)&&!game.seen.has('bark')){game.seen.add('bark');play('bark');}
  }
  async function previewMenu(){
    if(menuPreviewPending||voices.get('menu')?.size)return;
    const epoch=playbackEpoch;menuPreviewPending=true;
    try{if(await unlock()&&epoch===playbackEpoch)await play('menu');}
    finally{menuPreviewPending=false;}
  }
  function setVolume(value,preview=false){
    prefs.volume=Math.max(0,Math.min(1,Number(value)||0));
    if(preview)prefs.enabled=true;
    savePrefs();
    if(master)master.gain.setTargetAtTime(prefs.enabled?prefs.volume:0,context.currentTime,.015);
    refreshUI();if(preview)void previewMenu();
  }
  function attachSettings(svg){
    const slot=svg.querySelector('#sound-volume-control');
    if(!slot||slot.querySelector('.duck-volume-live'))return;
    // Use native SVG controls: foreignObject/input can be blocked by the host.
    const doc=svg.ownerDocument,ns='http://www.w3.org/2000/svg';
    const fallback=slot.querySelector('.volume-fallback');
    if(!fallback)return;
    const track=fallback.querySelector('rect'),knob=fallback.querySelector('circle');
    const output=[...fallback.querySelectorAll('text')].at(-1);
    if(!track||!knob||!output)return;
    // Pikuco may store geometry in CSS; attributes alone can be missing or overridden.
    const geometry=(element,name,fallback)=>{
      const computed=parseFloat(style(element).getPropertyValue(name));
      const attribute=parseFloat(element.getAttribute(name));
      return Number.isFinite(computed)?computed:Number.isFinite(attribute)?attribute:fallback;
    };
    const left=geometry(track,'x',181),width=geometry(track,'width',330)||330;
    const cy=geometry(knob,'cy',352.5);
    const input=doc.createElementNS(ns,'rect');
    for(const [key,value]of Object.entries({class:'duck-volume-live',x:left-12,y:cy-20,width:width+24,height:40,tabindex:0,role:'slider','aria-label':'Громкость','aria-valuemin':0,'aria-valuemax':100}))input.setAttribute(key,String(value));
    input.style.cssText='fill:#fff!important;fill-opacity:.001!important;pointer-events:all!important;cursor:pointer!important;touch-action:none!important;';
    for(const property of ['x','y','width','height'])input.style.setProperty(property,input.getAttribute(property)+'px','important');
    slot.append(input);
    let dragging=null;
    const fromPointer=event=>{
      const matrix=slot.getScreenCTM();if(!matrix)return;
      const point=svg.createSVGPoint();point.x=event.clientX;point.y=event.clientY;
      const local=point.matrixTransform(matrix.inverse());
      setVolume((local.x-left)/width,true);
    };
    input.addEventListener('pointerdown',event=>{
      if(event.button!==0)return;
      event.preventDefault();event.stopPropagation();input.focus();dragging=event.pointerId;
      input.setPointerCapture?.(dragging);fromPointer(event);
    });
    input.addEventListener('pointermove',event=>{if(event.pointerId===dragging)fromPointer(event);});
    const release=event=>{if(event.pointerId===dragging)dragging=null;};
    input.addEventListener('pointerup',release);input.addEventListener('pointercancel',release);input.addEventListener('lostpointercapture',release);
    input.addEventListener('keydown',event=>{
      let value=prefs.volume;
      if(event.key==='ArrowRight'||event.key==='ArrowUp')value+=.01;
      else if(event.key==='ArrowLeft'||event.key==='ArrowDown')value-=.01;
      else if(event.key==='PageUp')value+=.1;
      else if(event.key==='PageDown')value-=.1;
      else if(event.key==='Home')value=0;
      else if(event.key==='End')value=1;
      else return;
      event.preventDefault();event.stopPropagation();setVolume(value,true);
    });
    settingsControls.add({svg,slot,input,output,knob,left,width});refreshUI();
  }
  function bind(svg) {
    if(games.has(svg)){attachSettings(svg);return;}
    if(!svg.querySelector('.v[data-volley] .q'))return;
    const target=targetIn(svg);
    const game={svg,lastTarget:target?.id||'',started:!!target&&(target.id==='astart'||target.classList.contains('q')),ended:false,hits:new Set(),seen:new Set(),volleys:[...svg.querySelectorAll('.v[data-volley]')],results:[...svg.querySelectorAll('.result')].filter(e=>e.textContent.includes('ROUND CLEAR')),overs:[...svg.querySelectorAll('.over')],win:svg.querySelector('.win'),intro:svg.querySelector('.intro')};
    // Baseline existing state when the script is enabled halfway through a game.
    for(const v of game.volleys){const id=v.querySelector('.bird[data-duck]')?.dataset.duck;if(id&&Number(style(svg).getPropertyValue('--d'+id))>.5)game.hits.add(v.dataset.volley);}
    games.set(svg,game);if(target)activeRoot=svg;attachSettings(svg);
    svg.addEventListener('pointerdown',event=>{if(event.target.closest?.('a')){activeRoot=svg;void unlock();}},{capture:true,passive:true});
    svg.addEventListener('click',()=>{setTimeout(()=>handleTarget(game),0);},{capture:true});
    svg.ownerDocument.defaultView.addEventListener('hashchange',()=>handleTarget(game));
    refreshUI();
  }
  function scan(doc=document,depth=0) {
    try {
      for(const svg of doc.querySelectorAll('svg'))if(svg.querySelector('.v[data-volley] .q'))bind(svg);
      if(depth<2)for(const frame of doc.querySelectorAll('object,iframe,embed')){
        try {const child=frame.contentDocument||frame.getSVGDocument?.();if(child&&child!==doc)scan(child,depth+1);}catch{}
      }
    }catch(error){report(error);}
    refreshUI();
  }
  function refreshUI(message) {
    for(const control of settingsControls){
      if(!control.svg.isConnected||!control.input.isConnected){settingsControls.delete(control);continue;}
      const percent=Math.round(prefs.volume*100);
      control.input.setAttribute('aria-valuenow',String(percent));
      control.input.setAttribute('aria-valuetext',percent+'%');
      const cx=control.left+control.width*prefs.volume;
      control.knob.setAttribute('cx',String(cx));
      control.knob.style.setProperty('cx',cx+'px','important');
      control.output.textContent=percent+'%';
    }
  }
  Object.defineProperty(window,'DuckHuntAudio',{value:Object.freeze({snapshot:()=>({version:'1.2.3',volume:prefs.volume,enabled:prefs.enabled,events:{...stats.events},errors:[...stats.errors],decoded:[...stats.decoded],state:context?.state||'not-started',games:games.size,custom:[...stored.keys()]}),preview:async name=>{if(Object.hasOwn(PACK,name)&&await unlock())await play(name);}})});
  void loadStored();scan();
  setInterval(()=>{for(const [svg,game]of games){if(!svg.isConnected){games.delete(svg);continue;}try{pollGame(game);}catch(error){report(error);}}},75);
  setInterval(()=>scan(),1500);
})();
